from __future__ import annotations

PAGE = r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>实验样本证据链</title>
<style>
:root{--ink:#17202a;--muted:#657386;--line:#d8dee8;--bg:#f5f7fb;--card:#fff;--blue:#1e63d6;--red:#b4232a;--green:#177245;--amber:#9a6200}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#102748;color:white;padding:22px 28px}header h1{margin:0;font-size:24px}.wrap{max-width:1280px;margin:0 auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;box-shadow:0 1px 3px #24344d14}h2{font-size:17px;margin:0 0 12px}h3{font-size:15px;margin:14px 0 8px}label{display:block;margin:8px 0;font-weight:600}input,textarea,select{width:100%;border:1px solid var(--line);border-radius:7px;padding:8px;font:inherit;background:white}textarea{min-height:150px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}button{border:0;border-radius:7px;padding:8px 12px;background:var(--blue);color:white;font-weight:700;cursor:pointer}button.secondary{background:#526070}button.danger{background:var(--red)}button.small{padding:4px 8px;font-size:12px}button:hover{filter:brightness(.96)}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border-bottom:1px solid var(--line);padding:7px;text-align:left;vertical-align:top}th{color:#42526a;background:#f3f6fa}.pill{display:inline-block;border-radius:99px;padding:2px 8px;font-size:12px;font-weight:700}.accepted,.duplicate{background:#dff3e8;color:var(--green)}.quarantined{background:#fdebd2;color:var(--amber)}.ignored{background:#e7e9ee;color:#526070}.parallel_facts{background:#fff0c2;color:var(--amber)}pre{background:#0d1b2a;color:#e8eef8;padding:12px;border-radius:8px;overflow:auto;max-height:360px;font-size:12px}.muted{color:var(--muted)}.ok{color:var(--green);font-weight:700}.warn{color:var(--amber);font-weight:700}.bad{color:var(--red);font-weight:700}.notice{border-left:4px solid var(--amber);padding:10px;background:#fff8e8;border-radius:6px;margin-bottom:12px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.full{grid-column:1/-1}.hidden{display:none}
</style>
</head>
<body>
<header><h1>实验样本证据链</h1><div>离线多站点采集、处理、分装、销毁与中心合并演示</div></header>
<main class="wrap">
  <div class="notice"><strong>预置示例：</strong>GAMMA 的第 2 个包先到中心并进入隔离，第 1 个包到达后自动补齐释放；DELTA 篡改包仍在隔离。S-100 保留两个站点的并行事实，并由 CENTER 的显式 reconciliation 裁决。</div>
  <div id="message"></div>
  <div class="grid">
    <section class="card"><h2>新建站点</h2><label>站点 ID<input id="siteId" placeholder="NORTH"></label><label>名称<input id="siteName" placeholder="北部站点"></label><button onclick="createSite()">创建带测试密钥站点</button><p class="muted">中心只保存测试私钥；导出包不包含私钥。</p></section>
    <section class="card"><h2>录入不可变事件</h2><textarea id="eventJson"></textarea><p><button onclick="recordEvent()">追加事件</button> <span class="muted">recorded_at 可晚于 effective_at</span></p></section>
    <section class="card"><h2>导出签名包</h2><label>站点 ID<input id="exportSite" placeholder="ALPHA"></label><label>最多事件数（空=全部）<input id="exportLimit" type="number" min="1"></label><button onclick="exportPackage()">生成并下载包</button><p><button class="secondary" onclick="rotateKey()">轮换该站点密钥</button></p></section>
    <section class="card full"><h2>导入事件包</h2><input type="file" id="importFile" accept=".json,application/json"><h3>或粘贴 JSON</h3><textarea id="importJson" placeholder="粘贴签名事件包"></textarea><p><button onclick="importPackage()">导入并原子校验</button></p></section>
    <section class="card full"><h2>样本状态与完整来源链</h2><div class="row"><input id="querySample" placeholder="样本 ID，例如 S-100"><input id="queryAt" placeholder="时间点 ISO-8601，可留空"></div><div class="row"><select id="queryBasis"><option value="effective">按 effective_at 截止</option><option value="recorded">按 recorded_at 截止</option></select><button onclick="loadSample()">查询</button></div><div id="sampleView" class="muted">选择样本或点击下表。</div></section>
    <section class="card full"><h2>样本</h2><div id="samples"></div></section>
    <section class="card"><h2>站点与链头</h2><div id="sites"></div></section>
    <section class="card"><h2>隔离与导入记录</h2><div id="quarantine"></div></section>
    <section class="card full"><h2>事件序列</h2><div id="events"></div></section>
    <section class="card full"><h2>导出批次</h2><div id="exports"></div></section>
  </div>
</main>
<script>
const $=(id)=>document.getElementById(id);
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function pretty(v){return JSON.stringify(v,null,2)}
function notify(text, ok=true){$("message").innerHTML=`<div class="card ${ok?"ok":"bad"}">${esc(text)}</div>`;setTimeout(()=>$("message").innerHTML="",5000)}
async function api(path, options={}){const res=await fetch(path,{headers:{"Content-Type":"application/json"},...options});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||res.statusText);return data}
function eventTemplate(){return pretty({site_id:"ALPHA",sample_id:"S-200",type:"processed",payload:{process:"freeze",location:"Alpha Lab",operator:"A. Lin"},effective_at:"2026-09-30T12:00:00Z",recorded_at:"2026-09-30T12:30:00Z"},null,2)}
$("eventJson").value=eventTemplate();
async function createSite(){try{const data=await api("/api/sites",{method:"POST",body:pretty({site_id:$("siteId").value,name:$("siteName").value})});notify(`站点 ${data.site_id} 已创建，kid=${data.kid}`);await refresh()}catch(e){notify(e.message,false)}}
async function recordEvent(){try{const data=await api("/api/events",{method:"POST",body:$("eventJson").value});notify(`事件 ${data.event_id} 已追加，seq=${data.seq}`);await refresh()}catch(e){notify(e.message,false)}}
async function rotateKey(){try{const data=await api(`/api/sites/${encodeURIComponent($("exportSite").value)}/rotate-key`,{method:"POST",body:"{}"});notify(`密钥轮换待导出：${data.old_kid} → ${data.new_kid}`);await refresh()}catch(e){notify(e.message,false)}}
async function exportPackage(){try{const limit=$("exportLimit").value;const body={};if(limit)body.max_events=Number(limit);const data=await api(`/api/sites/${encodeURIComponent($("exportSite").value)}/exports`,{method:"POST",body:pretty(body)});const blob=new Blob([pretty(data)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${data.site_id}-${data.start_seq}-${data.end_seq}.json`;a.click();notify("已生成签名包；包内没有私钥");await refresh()}catch(e){notify(e.message,false)}}
async function importPackage(){let text=$("importJson").value;const file=$("importFile").files[0];if(file)text=await file.text();try{const data=await api("/api/imports",{method:"POST",body:text});notify(`导入结果：${data.status}${data.reason?(" - "+data.reason):""}`,data.status!=="quarantined");await refresh()}catch(e){notify(e.message,false)}}
function pill(s){return `<span class="pill ${esc(s)}">${esc(s)}</span>`}
function table(cols,rows){if(!rows.length)return `<p class="muted">暂无记录</p>`;return `<table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c.render(r)}</td>`).join("")}</tr>`).join("")}</tbody></table>`}
async function refresh(){const [sites,samples,events,quarantine,exports]=await Promise.all([api("/api/sites"),api("/api/samples"),api("/api/events"),api("/api/quarantine"),api("/api/exports")]);$("sites").innerHTML=table([{label:"站点",render:r=>`<strong>${esc(r.site_id)}</strong><br><span class="muted">${esc(r.name)}</span>`},{label:"链头",render:r=>`seq ${r.last_seq}<br><span class="mono">${esc(r.last_hash.slice(0,16))}…</span>`},{label:"当前密钥",render:r=>esc(r.current_kid)},{label:"待轮换",render:r=>(r.pending_rotations||[]).map(x=>x.new_kid).join(",")}],sites);$("samples").innerHTML=table([{label:"样本",render:r=>`<a href="#" onclick="loadOne('${esc(r.sample_id)}');return false">${esc(r.sample_id)}</a>`},{label:"派生状态",render:r=>pill(r.derived_status||"无")},{label:"事实站点",render:r=>esc(r.sites)},{label:"事件",render:r=>r.event_count},{label:"生效时间/记录时间",render:r=>`${esc(r.first_effective_at)}<br><span class="muted">${esc(r.last_recorded_at)}</span>`}],samples);$("events").innerHTML=table([{label:"站点 seq",render:r=>`${esc(r.site_id)} #${r.seq}`},{label:"ID/类型",render:r=>`${esc(r.event_id)}<br>${pill(r.type)}`},{label:"样本",render:r=>esc(r.sample_id)},{label:"effective_at",render:r=>esc(r.effective_at)},{label:"recorded_at",render:r=>esc(r.recorded_at)},{label:"payload",render:r=>`<pre>${esc(pretty(r.payload))}</pre>`},{label:"哈希",render:r=>`<span class="mono">${esc(r.event_hash.slice(0,12))}…</span>`}],events);$("quarantine").innerHTML=table([{label:"ID",render:r=>r.id},{label:"状态",render:r=>pill(r.status)},{label:"站点/范围",render:r=>`${esc(r.site_id||"-")} ${r.start_seq??""}-${r.end_seq??""}`},{label:"原因",render:r=>esc(r.reason||"")},{label:"导入/释放",render:r=>`${esc(r.imported_at)}<br><span class="muted">${esc(r.released_at||"")}</span>`},{label:"操作",render:r=>r.status==="quarantined"?`<button class="small" onclick="retry(${r.id})">重试</button> <button class="small danger" onclick="ignoreQ(${r.id})">忽略</button>`:""}],quarantine);$("exports").innerHTML=table([{label:"ID",render:r=>r.id},{label:"站点",render:r=>esc(r.site_id)},{label:"范围",render:r=>`${r.start_seq}-${r.end_seq}`},{label:"创建",render:r=>esc(r.created_at)},{label:"包",render:r=>`<button class="small secondary" onclick="downloadExport(${r.id})">查看/下载</button>`}],exports)}
async function retry(id){try{notify(pretty(await api(`/api/quarantine/${id}/retry`,{method:"POST",body:"{}"})));await refresh()}catch(e){notify(e.message,false)}}
async function ignoreQ(id){try{await api(`/api/quarantine/${id}/ignore`,{method:"POST",body:"{}"});await refresh()}catch(e){notify(e.message,false)}}
async function downloadExport(id){const data=await api(`/api/exports/${id}`);const blob=new Blob([pretty(data)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`export-${id}.json`;a.click()}
async function loadOne(id){$("querySample").value=id;await loadSample()}
async function loadSample(){try{const id=$("querySample").value.trim();if(!id)return;const params=new URLSearchParams;if($("queryAt").value)params.set("at",$("queryAt").value);params.set("basis",$("queryBasis").value);const data=await api(`/api/samples/${encodeURIComponent(id)}?${params}`);$("sampleView").innerHTML=`<h3>派生状态</h3><pre>${esc(pretty(data.state))}</pre><h3>固定排序规则：${esc(data.sorting_rule)}</h3><h3>完整来源链</h3><table><thead><tr><th>站点 #</th><th>事件</th><th>effective_at</th><th>recorded_at</th><th>payload</th></tr></thead><tbody>${data.timeline.map(e=>`<tr><td>${esc(e.site_id)} #${e.seq}</td><td>${esc(e.event_id)}<br>${pill(e.type)}</td><td>${esc(e.effective_at)}</td><td>${esc(e.recorded_at)}</td><td><pre>${esc(pretty(e.payload))}</pre></td></tr>`).join("")}</tbody></table>`}catch(e){notify(e.message,false)}}
refresh();
</script>
</body>
</html>'''
